import json
from typing import Any, Dict

def _load(v):
    if isinstance(v, list):
        return v
    if isinstance(v, dict):
        return [v]
    if not isinstance(v, str) or not v.strip():
        return []
    try:
        obj = json.loads(v)
        if isinstance(obj, dict) and isinstance(obj.get('offers'), list):
            return obj['offers']
        return obj if isinstance(obj, list) else ([obj] if isinstance(obj, dict) else [])
    except Exception:
        return []

async def main(args):
    raw = args.params.get('offers')
    top_approval_id = ''
    if isinstance(raw, dict):
        top_approval_id = str(raw.get('approval_id') or '')
    offers = [o for o in _load(raw) if isinstance(o, dict)]
    first = offers[0] if offers else {}
    req_id = str(args.params.get('req_id') or first.get('req_id') or '')
    ret: Output = {
        'req_id': req_id,
        'offer_id': str(first.get('offer_id') or ''),
        'approval_id': str(top_approval_id or first.get('approval_id') or ''),
        'approval_type': str(first.get('approval_type') or ''),
        'offers': json.dumps(offers, ensure_ascii=False)
    }
    return ret

from typing import Any, Dict

def _csv(v):
    # offers 入参可能是 JSON 数组字符串或已归一数组，拍平为 offer_id 逗号串
    import json as _json
    if isinstance(v, str):
        s = v.strip()
        if not s:
            return ''
        try:
            v = _json.loads(s)
        except Exception:
            v = s
    if isinstance(v, dict) and isinstance(v.get('offers'), list):
        v = v['offers']
    if not isinstance(v, list):
        return ''
    ids = []
    for o in v:
        oid = str((o or {}).get('offer_id') or '') if isinstance(o, dict) else ''
        if oid:
            ids.append(oid)
    return ','.join(ids)

def _first_offer(v):
    # 归一 offers 入参（JSON 字符串/数组/含 offers 包装）取首个商品
    import json as _json
    if isinstance(v, str):
        s = v.strip()
        if not s:
            return None
        try:
            v = _json.loads(s)
        except Exception:
            return None
    if isinstance(v, dict) and isinstance(v.get('offers'), list):
        v = v['offers']
    if not isinstance(v, list) or not v:
        return None
    return next((o for o in v if isinstance(o, dict)), None)

def _matrix(v):
    # 取首个商品的 approval_matrix（已是 list）
    import json as _json
    first = _first_offer(v)
    if not first:
        return None
    m = first.get('approval_matrix')
    if isinstance(m, str):
        try:
            m = _json.loads(m)
        except Exception:
            m = None
    if not isinstance(m, list) or not m:
        return None
    return [n for n in m if isinstance(n, dict)]

def _passed(n):
    return '已通过' in str(n.get('status') or '')

def _rejected(n):
    s = str(n.get('status') or '')
    return ('驳回' in s) or ('未通过' in s) or ('拒绝' in s)

def _step_stage(v):
    # 依据审批矩阵节点级 stage/status 计算真实业务进度（navs 索引）；无法判定返回 None
    nodes = _matrix(v)
    if not nodes:
        # 无矩阵：优化工单回落上线审批环节，其余无法判定
        first = _first_offer(v)
        return 7 if (first and str(first.get('work_order_type') or '') == 'optimize') else None
    req_nodes = [n for n in nodes if str(n.get('stage') or '') == 'requirement']
    launch_nodes = [n for n in nodes if str(n.get('stage') or '') == 'launch']
    rejected = [n for n in nodes if _rejected(n)]
    if rejected:
        return 0 if str(rejected[0].get('stage') or '') == 'requirement' else 7
    if req_nodes and not all(_passed(n) for n in req_nodes):
        return 0
    if launch_nodes and not all(_passed(n) for n in launch_nodes):
        return 1
    return 8

def _approval_nodes(v):
    # 生成页面审批矩阵页签数据：只保留「已开始阶段」（该阶段至少一节点非待审核/未开始/空），
    # 且各阶段内截断到首个非「已通过」节点（含）；无矩阵返回 ''
    import json as _json
    nodes = _matrix(v)
    if not nodes:
        return ''
    def _started(n):
        s = str(n.get('status') or '').strip()
        return s not in ('', '待审核', '未开始', '待处理')
    stages = []
    for n in nodes:
        st = str(n.get('stage') or '')
        if st not in stages:
            stages.append(st)
    keep = []
    for st in stages:
        sn = [n for n in nodes if str(n.get('stage') or '') == st]
        if not any(_started(n) for n in sn):
            continue
        for n in sn:
            keep.append({
                'seq': n.get('node_seq') or n.get('seq') or '',
                'stage': '需求' if st == 'requirement' else ('上线' if st == 'launch' else st),
                'node': str(n.get('node_name') or n.get('name') or ''),
                'role': str(n.get('approver') or n.get('role') or ''),
                'status': str(n.get('status') or ''),
                'opinion': str(n.get('opinion') or ''),
                'time': str(n.get('update_time') or ''),
                'pass': _passed(n)
            })
            if not _passed(n):
                break
    return _json.dumps(keep, ensure_ascii=False)

async def main(args):
    p = args.params
    chat_id = str(p.get('chat_id') or '')
    offer_id = str(p.get('offer_id') or '')
    offer_name = str(p.get('offer_name') or '')
    req_id = str(p.get('req_id') or '')
    offers_csv = _csv(p.get('offers'))
    qs = ('?chatId=' + chat_id + '&req_id=' + req_id + '&stage=08&view=stage')
    if offer_id:
        qs = ('?offer_id=' + offer_id + '&name=' + offer_name + '&chatId=' + chat_id + '&req_id=' + req_id + '&stage=08&view=stage')
    step_stage = _step_stage(p.get('approval_data'))
    if step_stage is not None:
        qs += '&step_stage=' + str(step_stage)
    anodes = _approval_nodes(p.get('approval_data'))
    if anodes:
        qs += '&approval_nodes=' + anodes
    _first = _first_offer(p.get('approval_data'))
    if _first and str(_first.get('work_order_type') or ''):
        qs += '&wo_type=' + str(_first.get('work_order_type'))
    if offers_csv:
        qs += '&offers=' + offers_csv
    biz_url = 'http://10.86.13.201:31280/prod-ai/ops-web/config-workbench.html' + qs
    panel = (
        "\n\n```xsbot-panel\n"
        + '{"version":"1.0","message_id":"' + chat_id + '",'
        + '"panels":[{"panel":"right","mode":"external","url":"' + biz_url + '","title":"上线审批看板"}]}'
        + "\n```\n"
    )
    result: Output = {'panel': panel}
    return result
